1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// These tests cover the CLI contract for a damaged committed circuit
13	// record: when name/version/constraints/public_inputs/private_inputs/frozen/
14	// description is missing, null, mistyped or duplicated, every data command
15	// must fail at read time with exit code 3, name the damaged field, print no
16	// success output, and leave data.json byte-for-byte in place.
17	
18	// cliFieldDamage damages one top-level field of the first circuit record
19	// through the generic JSON representation.
20	func cliFieldDamage(t *testing.T, dir string, mutate func(map[string]any)) []byte {
21		t.Helper()
22		path := filepath.Join(dir, "data.json")
23		raw, err := os.ReadFile(path)
24		if err != nil {
25			t.Fatal(err)
26		}
27		var env map[string]any
28		if err := json.Unmarshal(raw, &env); err != nil {
29			t.Fatal(err)
30		}
31		mutate(cliCircuit(env))
32		bad, err := json.MarshalIndent(env, "", "  ")
33		if err != nil {
34			t.Fatal(err)
35		}
36		bad = append(bad, '\n')
37		if err := os.WriteFile(path, bad, 0o644); err != nil {
38			t.Fatal(err)
39		}
40		return bad
41	}
42	
43	// cliDuplicateField rewrites the first circuit record's JSON text so that
44	// field appears a second time with extra. escaped spells one byte of the
45	// field key as a \u00XX escape.
46	func cliDuplicateField(t *testing.T, dir, field, extra string, escaped bool) []byte {
47		t.Helper()
48		path := filepath.Join(dir, "data.json")
49		raw, err := os.ReadFile(path)
50		if err != nil {
51			t.Fatal(err)
52		}
53		var wire struct {
54			Circuits []json.RawMessage `json:"circuits"`
55		}
56		if err := json.Unmarshal(raw, &wire); err != nil {
57			t.Fatal(err)
58		}
59		rec := []byte(wire.Circuits[0])
60		var compact bytes.Buffer
61		if err := json.Compact(&compact, rec); err != nil {
62			t.Fatal(err)
63		}
64		key := `"` + field + `"`
65		if escaped {
66			key = "\"\\u" + toHex(field[0]) + field[1:] + "\""
67		}
68		dup := append([]byte(nil), compact.Bytes()[:len(compact.Bytes())-1]...)
69		dup = append(dup, []byte(","+key+":"+extra+"}")...)
70		bad := bytes.Replace(raw, rec, dup, 1)
71		if err := os.WriteFile(path, bad, 0o644); err != nil {
72			t.Fatal(err)
73		}
74		return bad
75	}
76	
77	func toHex(b byte) string {
78		const hex = "0123456789abcdef"
79		return string([]byte{hex[b>>4], hex[b&0xf]})
80	}
81	
82	// assertCLIReadFailure runs commands against a damaged directory and checks
83	// the exit-3 contract: the error names both the damaged field and the
84	// circuit record, stdout stays empty and data.json is never rewritten.
85	func assertCLIReadFailure(t *testing.T, dir string, bad []byte, field string, frozen bool, commands ...[]string) {
86		t.Helper()
87		if len(commands) == 0 {
88			commands = [][]string{
89				{"circuit-list", "--dir", dir},
90				{"circuit-get", "--dir", dir, "--name", "mul", "--version", "1"},
91				{"job-list", "--dir", dir},
92			}
93			if frozen {
94				commands = append(commands,
95					[]string{"circuit-compile", "--dir", dir, "--name", "mul", "--version", "1"})
96			} else {
97				commands = append(commands,
98					[]string{"circuit-freeze", "--dir", dir, "--name", "mul", "--version", "1"},
99					[]string{"circuit-update", "--dir", dir, "--name", "mul", "--version", "1",
100						"--constraints", "2"})
101			}
102		}
