75			"lone continuation byte":   "bad\x80name",
76			"truncated multi-byte":     "trunc\xe4\xb8",
77			"overlong encoding":        "over\xc0\xaf",
78			"invalid byte 0xff":        "bad\xff",
79			"encoded surrogate half":   "pair\xed\xa0\x80",
80			"truncated at end":         "end\xc3",
81			"continuation then ASCII":  "bad\x80x",
