121			"has�mark",      // an actually committed replacement character
122			`literal\uD800`, // the literal six characters \uD800 — no escape
123			"mixed 电路😀�mix", // everything together
124		}
125		for _, name := range names {
126			if _, err := s.CreateCircuit(Circuit{Name: name, Version: 1, Constraints: 1}); err != nil {
