158	func TestCorruptNameInvalidUTF8Refused(t *testing.T) {
159		bad := map[string]string{
160			"lone continuation byte": "\"bad\x80name\"",
161			"invalid byte 0xff":      "\"bad\xff\"",
162			"truncated multi-byte":   "\"trunc\xe4\xb8\"",
163			"overlong encoding":      "\"over\xc0\xaf\"",
164			"encoded surrogate half": "\"pair\xed\xa0\x80\"",
165		}
166		for label, nameJSON := range bad {
167			t.Run(label, func(t *testing.T) {
